"""Run the real Ruby selector against permissions generated by the real SLICC compiler.

Only controllers/network/memory are in-memory test doubles; neither the permission
mapping nor RubySystem's functional read/write algorithm is reimplemented here.
Changing IM back to Busy must break test_clean_fetch_reads_authoritative_memory.
"""
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
GEM5 = ROOT / 'gem5-fs'


def declaration(text, signature):
    start = text.index(signature)
    opening = text.index('{', start)
    level = 1
    end = opening + 1
    while level:
        level += (text[end] == '{') - (text[end] == '}')
        end += 1
    return text[start:end]


class RubyCleanFetchTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory(dir=ROOT / 'tmp')
        cls.addClassCleanup(cls.temp.cleanup)
        work = Path(cls.temp.name)
        compiler_path = [GEM5 / 'src/mem', GEM5 / 'build_tools', GEM5 / 'ext/ply']
        script = '''from slicc.parser import SLICC
from pathlib import Path
import sys
p=Path(sys.argv[1]);out=sys.argv[2]
s=SLICC(str(p/'MESI_Three_Level.slicc'),[str(p/'RubySlicc_interfaces.slicc')],str(p))
s.process();s.writeCodeFiles(out,[])
'''
        env = dict(os.environ, PYTHONPATH=os.pathsep.join(map(str, compiler_path)))
        subprocess.run([sys.executable, '-c', script,
                        str(GEM5 / 'src/mem/ruby/protocol'), str(work / 'generated')],
                       cwd=work, env=env, check=True, capture_output=True, text=True)
        generated = work / 'generated'
        state = next(generated.rglob('Directory_State.cc')).read_text()
        state_h = next(generated.rglob('Directory_State.hh')).read_text()
        permission_h = next(generated.rglob('AccessPermission.hh')).read_text()
        ruby = (GEM5 / 'src/mem/ruby/system/RubySystem.cc').read_text()
        fixture = (ROOT / 'tests/fixtures/ruby_clean_fetch_functional_read.cc').read_text()
        parts = {
            '// GENERATED_PERMISSION_ENUM': declaration(permission_h, 'enum AccessPermission {') + ';',
            '// GENERATED_STATE_ENUM': declaration(state_h, 'enum Directory_State {') + ';',
            '// GENERATED_STATE_PERMISSIONS': declaration(state, 'AccessPermission Directory_State_to_permission'),
            '// PRODUCTION_FUNCTIONAL_READ': declaration(ruby, 'bool\nRubySystem::simpleFunctionalRead'),
            '// PRODUCTION_FUNCTIONAL_WRITE': declaration(ruby, 'bool\nRubySystem::functionalWrite'),
        }
        for marker, content in parts.items():
            fixture = fixture.replace(marker, content)
        (work / 'test.cc').write_text(fixture)
        cls.binary = work / 'test'
        compiled = subprocess.run(['/opt/gcc-11/bin/g++', '-std=c++17', '-O0',
                                   '-Wl,-rpath,/opt/gcc-11/lib64', str(work / 'test.cc'),
                                   '-o', str(cls.binary)], capture_output=True, text=True)
        if compiled.returncode:
            raise RuntimeError(compiled.stderr)

    def run_case(self, case):
        result = subprocess.run([str(self.binary), case], capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_clean_fetch_reads_authoritative_memory(self): self.run_case('clean-im')
    def test_idle_directory_still_reads_memory(self): self.run_case('idle')
    def test_modified_cache_owner_beats_memory(self): self.run_case('owner')
    def test_pending_writeback_data_beats_stale_memory(self): self.run_case('writeback')
    def test_inflight_network_data_remains_visible(self): self.run_case('network')
    def test_dirty_and_dma_busy_without_data_still_fail(self): self.run_case('busy')
    def test_missing_line_still_fails(self): self.run_case('missing')
    def test_functional_write_updates_memory_and_pending_copies(self): self.run_case('write')
    def test_unrelated_directory_permissions_unchanged(self): self.run_case('permissions')


if __name__ == '__main__':
    unittest.main()
